const fs = require('fs');
const path = require('path');

// ============================================================
// generar_453_chat_visitas.js
// ============================================================
// El chat aprende a responder sobre las VISITAS AL VETERINARIO, y no
// solo la fecha: tambien que se habia registrado esos dias.
//
//   Tú: ¿cuándo fue al veterinario?
//   Chiqui: La última vez que fueron al veterinario fue el 28 jul.
//           Esos días habías registrado: vomitó, heces blandas.
//           💬 "solo bilis y saliva"
//           En total llevas 2 visitas registradas.
//
// EL CRUCE es lo que hace util el dato. Una fecha sola no dice nada;
// con lo que pasaba alrededor si — y es justo lo que uno quiere
// recordar cuando vuelven los sintomas.
//
// Si esos dias no habia nada registrado, tambien lo dice: "esos días no
// habías registrado nada fuera de lo normal". Eso tambien es
// informacion.
//
// La ventana es de 5 dias alrededor de la visita.
//
// Este script solo actualiza el componente. Pasarle las visitas va en
// el siguiente.
//
// REQUISITO: script 451 desplegado.
//
// Si algo no calza, ABORTA sin escribir.
// ============================================================

const RUTA = 'components/ChiquiChat.tsx';
const CHAT_B64 = '';

function abortar(motivo) {
  console.log('');
  console.log('ABORTADO: ' + motivo);
  console.log('No se modifico ningun archivo. Avisale a Claude lo que dice este mensaje.');
  process.exit(1);
}

const destino = path.join(process.cwd(), RUTA);
if (!fs.existsSync(destino)) {
  abortar('no se encontro ' + RUTA + '. Corre primero el script 451.');
}

const actual = fs.readFileSync(destino, 'utf8');
if (actual.includes("case 'visitas'")) {
  abortar('el chat ya responde sobre visitas. Parece que este script ya se corrio.');
}
if (!actual.includes('const EMERGENCIAS')) {
  abortar('falta el script 451. Correlo primero.');
}

const comp = Buffer.from(CHAT_B64, 'base64').toString('utf8');

const REQUERIDOS = [
  "'use client'",
  'export default function ChiquiChat',
  "case 'visitas'",
  'La última vez que fueron al veterinario',
  'Esos días habías registrado',
  'fechaISO',
  'const EMERGENCIAS',
  'const ALIMENTOS',
];
for (const r of REQUERIDOS) {
  if (!comp.includes(r)) {
    abortar('el contenido nuevo no incluye [' + r + ']. Script corrupto, no se escribio nada.');
  }
}
if (comp.split('type Tema =').length - 1 !== 1) {
  abortar('type Tema deberia declararse una sola vez.');
}
console.log('  OK  el contenido nuevo responde sobre visitas');

fs.writeFileSync(destino, comp, 'utf8');
console.log('');
console.log('OK: ' + RUTA);
console.log('');
console.log('Listo. Falta pasarle las visitas: eso va en el siguiente script.');
